  "units": [
    {
      "section": "key_capabilities",
      "slot": "capability:1",
      "text": "Open existing PDF files with `Aspose.Pdf.Document`, including password-protected files by passing the user or owner password to the constructor, and inspect encryption state with `IsEncrypted()`; modify content by accessing `Pages`, `Info`, `Metadata`, `Outlines`, `Form`, `EmbeddedFiles`, and `NamedDestinations`, then save changes with `Save` while preserving original bytes for byte-verbatim round-trips or incremental `/Info` updates.",
      "fact_ids": [
        "example:002",
        "example:004",
        "public_symbol:aspose.pdf.document",
        "public_symbol:aspose.pdf.documentinfo"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:2",
      "text": "Extract text from a `Document` or single `Page` using `Aspose.Pdf.Text.TextAbsorber`, which walks the page content and returns the full text, or use `TextFragmentAbsorber` for positioned fragments with font, size, and colour details; render individual pages or ranges to raster images via `Aspose.Pdf.Devices.PngDevice`, `JpegDevice`, `BmpDevice`, or `TiffDevice` with configurable resolution and color depth.",
      "fact_ids": [
        "example:002",
        "public_symbol:aspose.pdf.devices",
        "public_symbol:aspose.pdf.text"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:3",
      "text": "Encrypt a document using `Aspose.Pdf.Document.Encrypt` with user and owner passwords, granular `Aspose.Pdf.Permissions` flags (print, modify, extract, annotate, fill form, accessibility, assemble, high-res print), and algorithms including RC4-40, RC4-128, AES-128, or AES-256 (PDF 2.0, R=6); sign documents with `Aspose.Pdf.Facades.PdfFileSignature` to add a detached PKCS#7 signature with byte-exact `/ByteRange`.",
      "fact_ids": [
        "example:007",
        "public_symbol:aspose.pdf.cryptoalgorithm",
        "public_symbol:aspose.pdf.facades",
        "public_symbol:aspose.pdf.permissions"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:4",
      "text": "Build documents from scratch using `Aspose.Pdf.Facades` and core classes: positioned text via `Aspose.Pdf.Text.TextBuilder`, `TextFragment`, and `TextParagraph` with font lookup through `FontRepository::FindFont`; tabular layout via `Table`, `Row`, and `Cell` with column widths, borders, background colours, and spanning; vector shapes via `Aspose.Pdf.Drawing.Graph` with `Line`, `Rectangle`, `Circle`, and `Ellipse`; and rotated overlays via `WatermarkArtifact`.",
      "fact_ids": [
        "example:001",
        "public_symbol:aspose.pdf.annotations",
        "public_symbol:aspose.pdf.drawing",
        "public_symbol:aspose.pdf.forms",
        "public_symbol:aspose.pdf.text"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:5",
      "text": "Support the Standard-14 fonts—`/Helvetica`, `/Times-Roman`, `/Courier`, and four styles each—by mapping them to system fonts or bundled Liberation substitutes (SIL OFL 1.1) so glyphs render correctly even in fontless Linux or CI environments, and text extracted through `TextDevice` uses a pluggable `Encoding` supporting UTF-8, UTF-16LE, UTF-16BE, Latin-1, and Windows-1252 output.",
      "fact_ids": [
        "public_symbol:aspose.pdf.text"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:6",
      "text": "Use the legacy `Aspose.Pdf.Facades` API classes—including `PdfConverter` for rasterising to multi-page TIFF or per-page PNG, `PdfExtractor` for text extraction with `StartPage`/`EndPage`, `PdfFileSecurity` for encrypt/decrypt and password changes, `PdfFileSignature` for signing, `PdfBookmarkEditor` for bookmarks, `PdfFileEditor` for concatenating and splitting via `Concatenate`, `SplitFromFirst`, `SplitToEnd`, and `SplitToPages`, and `PdfFileStamp` for headers, footers, and page numbers—each binding independently to a `Document`.",
      "fact_ids": [
        "public_symbol:aspose.pdf.facades"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:7",
      "text": "Read and write document metadata through typed `Aspose.Pdf.DocumentInfo` accessors for title, author, subject, keywords, creator, producer, and dates, plus `Add`, `Remove`, and `ClearCustomData` for arbitrary entries; access XMP metadata via `Aspose.Pdf.Metadata` with methods including `Add`, `Remove`, `Clear`, `Contains`, `ContainsKey`, `Count`, `GetNamespaceUriByPrefix`, `GetPrefixByNamespaceUri`, `IsFixedSize`, `IsReadOnly`, `Keys`, `RegisterNamespaceUri`, `TryGetValue`, `Values`, and `at`.",
      "fact_ids": [
        "example:005",
        "public_symbol:aspose.pdf.documentinfo",
        "public_symbol:aspose.pdf.metadata"
      ]
    },
    {
      "section": "key_capabilities",
      "slot": "capability:8",
      "text": "The package has no runtime dependencies, and its renderer produces raster images without requiring any third-party libraries or external runtime components.",
      "fact_ids": [
        "public_symbol:aspose.pdf.devices"
      ]
    }
  ],
